private static String unescape(String str){
  StringBuilder outBuffer = new StringBuilder(str.length());
  for (int index = 0; index < str.length(); ) {
    char c;
    try {
      c = str.charAt(index++);
      if (c == '\\') {
        c = str.charAt(index++);
        if (c == 't') {
          c = '\t';
        } else if (c == 'r') {
          c = '\r';
        } else if (c == 'n') {
          c = '\n';
        } else if (c == 'f') {
          c = '\f';
        }
      }
      outBuffer.append(c);
    } catch (IndexOutOfBoundsException e) {
      throw new IllegalArgumentException("Invalid escape sequence at the end of the string", e);
    }
  }
  return outBuffer.toString();
}
